pub(crate) fn maybe_expression_blocks(expr: Option<&Expr>, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) { expression_blocks(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, names, unaliased, holes_of, root_at, found); }

pub(crate) fn path_name(segments: &[winnow_grammar::Symbol], names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> String {
    let mut name = unaliased(names.resolve(*nikaia_std::index::get(&segments, 0)));
    for k in 1..segments.len() as i64 {
        let segment = names.resolve(*nikaia_std::index::get(&segments, (k) as usize));
        name = format!("{}::{}", name, segment);
    }
    name
}

pub(crate) fn named_at(name: String, span: &Span) -> Seen { Seen::Path { name, span: span.clone() } }

pub(crate) fn a_named_call(func: &Expr, args: &[Expr], span: &Span, names: &winnow_grammar::InternerContext, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    let name = match func {
        Expr::Variable(name, _) => { let name = *name; names.resolve(name).to_owned() },
        Expr::Path(segments, _) => written_path(names, segments),
        _ => String::from(""),
    };
    if name.is_empty() {
        found.seen.push(Seen::Opaque { span: span.clone() });
        return;
    }
    let at = root_at(&name);
    let mut wrote: Option<Wrote> = None;
    if at >= 0 && at < args.len() as i64 { wrote = written_root(names, nikaia_std::index::get(&args, nikaia_std::index::at(at))); }
    found.seen.push(Seen::Call { name, wrote, span: span.clone() });
}

